        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            comps.append((color, cells))

    # Find a component that is an exact, one-cell-wide L.
    markers = []
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
        if r0 == r1 or c0 == c1:
            continue
        if len(cells) != (r1-r0+1) + (c1-c0+1) - 1:
            continue
        s = set(cells)
        for cr in (r0, r1):
            for cc in (c0, c1):
                expected = {(cr, c) for c in range(c0, c1+1)}
                expected |= {(r, cc) for r in range(r0, r1+1)}
                if s == expected:
                    markers.append((max(r1-r0+1, c1-c0+1), len(cells),
                                    color, cells, cr, cc))
                    break

    if not markers:
        return [row[:] for row in grid]

    _, _, marker_color, marker, cr, cc = max(markers)
    mset = set(marker)

    # Determine which way the two arms extend from their shared corner.
    hdir = -1 if any((cr, c) in mset for c in range(cc-1, -1, -1)) else 1
    vdir = -1 if any((r, cc) in mset for r in range(cr-1, -1, -1)) else 1

    best = None
    for color, cells in comps:
        if color == marker_color:
            continue

        # Ignore straight multi-cell lines; these are not target objects.
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        if len(cells) > 1 and (min(rs) == max(rs) or min(cs) == max(cs)):
            continue

        # The quadrant between the two arms is not the side being indicated.
        mr = sum(rs) / len(rs)
        mc = sum(cs) / len(cs)
        if (mr - cr) * vdir > 0 and (mc - cc) * hdir > 0:
            continue

        dist = min(abs(r-mr0) + abs(c-mc0)
                   for r, c in cells for mr0, mc0 in marker)
        key = (dist, -len(cells))
        if best is None or key < best[0]:
            best = (key, color, cells)

    if best is None:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    for r, c in best[2]:
